CREATE OR REPLACE FUNCTION public.pcmso_valid_cpf(_cpf text) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE i integer; s integer; d integer; BEGIN IF _cpf IS NULL OR _cpf !~ '^[0-9]{11}$' OR _cpf ~ '^(\d)\1{10}$' THEN RETURN false; END IF; FOR i IN 10..11 LOOP s:=0; FOR d IN 1..i-1 LOOP s:=s+substring(_cpf,d,1)::integer*(i+1-d); END LOOP; d:=(s*10)%11; IF d=10 THEN d:=0; END IF; IF d<>substring(_cpf,i,1)::integer THEN RETURN false; END IF; END LOOP; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.pcmso_valid_cpf(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pcmso_valid_cpf(text) TO authenticated;